@startuml

class SmartHome {
  + address : string
}

class User {
  + name : string
}

class Room {}

abstract class Device {
  + deviceID : int
  + status : DeviceStatus
}

class Sensor extends Device {}

class Actuator extends Device {}

class SensorReading {
  + value : double
  + timestamp : datetime
}

class ControlCommand {
  + commandType : CommandType
  + commandStatus : CommandStatus
  + timestamp : datetime
}

class ActivityLog {}

class AutomationRule {
  + ruleStatus : RuleStatus
  + triggerTimestamp : datetime
}

abstract class BooleanExpression {}

class RelationalTerm extends BooleanExpression {}

class NotExpression extends BooleanExpression {}

class BinaryExpression extends BooleanExpression {}

class CommandSequence {}

enum DeviceStatus {
  Activated
  Deactivated
}

enum CommandType {
  lockDoor
  turnOnHeating
}

enum CommandStatus {
  Requested
  Completed
  Failed
}

enum RuleStatus {
  Created
  Edited
  Activated
  Deactivated
}

enum BinaryOp {
  AND
  OR
  NOT
}

User "*" -- "*" SmartHome : manages
SmartHome "1" *-- "*" Room
SmartHome "1" *-- "*" Device
SmartHome "1" *-- "1" ActivityLog
Room "1" *-- "*" Sensor
Room "1" *-- "*" Actuator
Sensor "1" -- "*" SensorReading
Actuator "1" -- "*" ControlCommand
ActivityLog "1" *-- "*" SensorReading
ActivityLog "1" *-- "*" ControlCommand
User "1" -- "*" AutomationRule : creates
AutomationRule "1" *-- "1" BooleanExpression : precondition
AutomationRule "1" *-- "1" CommandSequence : action
AutomationRule "0..1" -- "0..1" AutomationRule : depends on
AutomationRule "0..1" -- "0..1" AutomationRule : conflicts with
CommandSequence "1" *-- "1..*" ControlCommand
RelationalTerm "*" -- "0..1" Room
RelationalTerm "*" -- "0..1" Sensor
RelationalTerm "*" -- "0..1" Actuator
RelationalTerm "*" -- "0..1" SensorReading
RelationalTerm "*" -- "0..1" ControlCommand
NotExpression "1" -- "1" BooleanExpression : operand
BinaryExpression "1" -- "1" BooleanExpression : left
BinaryExpression "1" -- "1" BooleanExpression : right

@enduml

